import pulp

# Define the problem
model = pulp.LpProblem("TruckScheduling", pulp.LpMinimize)

# Data definition
trucks = [1, 2, 3, 4, 5, 6]
hubs = [1, 2, 3, 4, 5, 6]

# Truck schedules: List of (Hub, LoadingTime) in sequence
schedules = {
    1: [(5, 2), (6, 1), (1, 1), (2, 2), (4, 6), (3, 8)],
    2: [(3, 4), (1, 3), (4, 9), (2, 9), (6, 2), (5, 9)],
    3: [(2, 8), (1, 7), (6, 5), (3, 1), (4, 10), (5, 3)],
    4: [(4, 2), (2, 10), (6, 7), (3, 6), (1, 4), (5, 9)],
    5: [(4, 9), (1, 8), (6, 9), (3, 7), (5, 8), (2, 5)],
    6: [(2, 8), (6, 2), (3, 2), (1, 8), (5, 7), (4, 10)]
}

# Calculate processing times and identify operations
ops = []  # List of (Truck, OpIndex)
P = {}    # Processing time P[t][i]
H = {}    # Hub H[t][i]

for t in trucks:
    num_ops = len(schedules[t])
    P[t] = {}
    H[t] = {}
    for i in range(num_ops):
        hub, time = schedules[t][i]
        ops.append((t, i))
        P[t][i] = time
        H[t][i] = hub

# Big M value
M = 1000

# Decision Variables
# C[t][i]: Completion time of operation i of truck t
C = {}
for t in trucks:
    for i in range(len(schedules[t])):
        C[t, i] = pulp.LpVariable(f"C_{t}_{i}", lowBound=0, cat='Continuous')

# Z[t1, i1, t2, i2]: Binary variable for disjunctive constraints
# 1 if (t1, i1) precedes (t2, i2), 0 otherwise
Z = {}
for t1 in trucks:
    for i1 in range(len(schedules[t1])):
        for t2 in trucks:
            for i2 in range(len(schedules[t2])):
                if t1 < t2 and H[t1][i1] == H[t2][i2]:
                    Z[t1, i1, t2, i2] = pulp.LpVariable(f"Z_{t1}_{i1}_{t2}_{i2}", cat='Binary')

# C_max: The makespan (total completion time)
C_max = pulp.LpVariable("C_max", lowBound=0, cat='Continuous')

# Objective Function: Minimize C_max
model += C_max

# Constraints

# 1. Precedence Constraints: Operations must follow the truck's route sequence
for t in trucks:
    for i in range(len(schedules[t]) - 1):
        model += C[t, i+1] >= C[t, i] + P[t][i]

# 2. Disjunctive Constraints: Operations at the same hub cannot overlap
for t1 in trucks:
    for i1 in range(len(schedules[t1])):
        for t2 in trucks:
            for i2 in range(len(schedules[t2])):
                # Ensure we only compare pairs of different trucks
                if t1 < t2 and H[t1][i1] == H[t2][i2]:
                    # C[t1][i1] + P[t1][i1] <= C[t2][i2] + M * (1 - Z)
                    model += C[t1, i1] + P[t1][i1] <= C[t2, i2] + M * (1 - Z[t1, i1, t2, i2])

                    # C[t2][i2] + P[t2][i2] <= C[t1][i1] + M * Z
                    model += C[t2, i2] + P[t2][i2] <= C[t1, i1] + M * Z[t1, i1, t2, i2]

# 3. Makespan Constraints
# C_max must be greater than or equal to the completion time of the last operation of each truck
for t in trucks:
    last_op_index = len(schedules[t]) - 1
    model += C_max >= C[t, last_op_index]

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Total Completion Time (Makespan): {pulp.value(C_max)}")

print("\nDetailed Schedule:")
for t in trucks:
    print(f"Truck {t}:")
    for i in range(len(schedules[t])):
        hub = H[t][i]
        start_time = pulp.value(C[t, i]) - P[t][i]
        comp_time = pulp.value(C[t, i])
        print(f"  Op {i} at Hub {hub}: Start {start_time}, End {comp_time}")

import pulp

# Define the problem
model = pulp.LpProblem("plan", pulp.LpMinimize)

# Sets
J = [1, 2, 3]  # Shipments
H = [1, 2, 3]  # Hubs

# Data: Routes and Processing Times
# Route[j] is a list of tuples (h, p)
routes = {
    1: [(2, 2), (1, 2), (3, 6)],
    2: [(2, 7), (1, 6), (3, 10)],
    3: [(3, 8), (1, 9), (2, 5)]
}

# Extract processing times p[j][h]
p = {}
for j in J:
    p[j] = {}
    for h in H:
        p[j][h] = 0
    for step in routes[j]:
        h, duration = step
        p[j][h] = duration

# Extract operation sequences and predecessors
# ops[j] = list of hubs in order
ops = {j: [step[0] for step in routes[j]] for j in J}
# pred[j][h] = hub preceding h in j's route, or None
pred = {j: {} for j in J}
for j in J:
    for k in range(len(ops[j])):
        h = ops[j][k]
        if k > 0:
            pred[j][h] = ops[j][k-1]
        else:
            pred[j][h] = None

# Decision Variables
# C[j][h]: Completion time of shipment j at hub h
C = pulp.LpVariable.dicts("C", (J, H), lowBound=0, cat='Continuous')

# M: Big-M constant (sum of all processing times)
M = sum(p[j][h] for j in J for h in H)

# Binary variables for disjunctive constraints
# y[j1][j2][h] = 1 if j1 is processed before j2 at hub h, 0 otherwise
y = {}
for h in H:
    for j1 in J:
        for j2 in J:
            if j1 < j2:
                y[(j1, j2, h)] = pulp.LpVariable(f"y_{j1}_{j2}_{h}", cat='Binary')

# Objective Function: Minimize makespan (max completion time)
# We minimize the maximum completion time of the last operation of each job
last_ops = [C[j][ops[j][-1]] for j in J]
model += pulp.lpSum(last_ops)  # Minimizing sum of last ops minimizes makespan effectively in this context

# Constraints

# 1. Precedence Constraints (within a shipment)
for j in J:
    for h in ops[j]:
        if pred[j][h] is not None:
            h_prev = pred[j][h]
            # C[j][h] >= C[j][h_prev] + p[j][h]
            model += C[j][h] >= C[j][h_prev] + p[j][h]
        else:
            # First operation: C[j][h] >= p[j][h]
            model += C[j][h] >= p[j][h]

# 2. Disjunctive Constraints (at each hub)
for h in H:
    # Find shipments that visit hub h
    shipments_at_h = [j for j in J if p[j][h] > 0]
    for i in range(len(shipments_at_h)):
        for k in range(i + 1, len(shipments_at_h)):
            j1 = shipments_at_h[i]
            j2 = shipments_at_h[k]

            # C[j1][h] >= C[j2][h] + p[j1][h] OR C[j2][h] >= C[j1][h] + p[j2][h]
            # Using binary variable y[(j1, j2, h)]
            # If y=1, j1 is after j2 -> C[j1] >= C[j2] + p[j1]
            model += C[j1][h] >= C[j2][h] + p[j1][h] - M * (1 - y[(j1, j2, h)])
            # If y=0, j1 is before j2 -> C[j2] >= C[j1] + p[j2]
            model += C[j2][h] >= C[j1][h] + p[j2][h] - M * y[(j1, j2, h)]

# Solve the problem
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

import pulp

# --- Problem Data ---

# Trucks and Centers
trucks = [1, 2, 3, 4, 5, 6]
centers = [1, 2, 3, 4, 5, 6]

# Routes: List of (Center, Handling time) for each truck
# T1: (C5, 8) -> (C2, 8) -> (C4, 5) -> (C1, 1) -> (C3, 4) -> (C6, 9)
routes = {
    1: [(5, 8), (2, 8), (4, 5), (1, 1), (3, 4), (6, 9)],
    2: [(6, 2), (2, 5), (4, 3), (3, 10), (5, 7), (1, 4)],
    3: [(3, 6), (6, 4), (4, 6), (1, 8), (5, 4), (2, 5)],
    4: [(3, 3), (2, 6), (6, 1), (1, 8), (5, 1), (4, 1)],
    5: [(2, 1), (1, 6), (5, 7), (4, 3), (6, 4), (3, 8)],
    6: [(4, 7), (2, 7), (3, 1), (5, 7), (1, 5), (6, 9)]
}

# Indices for operations
# operations[t] is a list of step indices (0 to 5) for truck t
operations = {t: list(range(len(routes[t]))) for t in trucks}

# Processing time p[t][k]
p = {}
for t in trucks:
    for k, (c, time) in enumerate(routes[t]):
        p[(t, k)] = time

# Mapping operation to center
# center_of[t][k] returns the center ID for truck t at step k
center_of = {}
for t in trucks:
    for k, (c, time) in enumerate(routes[t]):
        center_of[(t, k)] = c

# --- Model Initialization ---

model = pulp.LpProblem("plan", pulp.LpMinimize)

# --- Decision Variables ---

# C[t][k]: Completion time of operation k of truck t
C = pulp.LpVariable.dicts("C", [(t, k) for t in trucks for k in operations[t]], lowBound=0, cat='Continuous')

# y[i][j][k][l]: Binary variable for disjunctive constraints
# 1 if operation (i, k) precedes operation (j, l), 0 otherwise
# Only needed for operations at the same center
y = {}
for i in trucks:
    for j in trucks:
        if i < j:
            for k in operations[i]:
                for l in operations[j]:
                    if center_of[(i, k)] == center_of[(j, l)]:
                        y[(i, k, j, l)] = pulp.LpVariable(f"y_{i}_{k}_{j}_{l}", cat='Binary')

# M: A sufficiently large number (Big M)
# Sum of all processing times is a safe upper bound for any sequence
M = sum([time for t in trucks for (c, time) in routes[t]])

# --- Objective Function ---

# Minimize the makespan (maximum completion time)
# We minimize a variable Z, where Z >= C[t][last_step]
Z = pulp.LpVariable("Z", lowBound=0, cat='Continuous')
model += Z

# --- Constraints ---

# 1. Precedence constraints (within each truck)
for t in trucks:
    for k_idx in range(len(operations[t]) - 1):
        curr_k = operations[t][k_idx]
        next_k = operations[t][k_idx + 1]
        model += C[(t, next_k)] >= C[(t, curr_k)] + p[(t, curr_k)]

# 2. Linking Z to completion times
for t in trucks:
    last_k = operations[t][-1]
    model += Z >= C[(t, last_k)]

# 3. Disjunctive constraints (no overlap at same center)
for i in trucks:
    for j in trucks:
        if i < j:
            for k in operations[i]:
                for l in operations[j]:
                    # Check if operations (i,k) and (j,l) are at the same center
                    if center_of[(i, k)] == center_of[(j, l)]:
                        # y = 1  => (i,k) before (j,l): C[j,l] >= C[i,k] + p[i,k]
                        # y = 0  => (j,l) before (i,k): C[i,k] >= C[j,l] + p[j,l]

                        model += C[(j, l)] >= C[(i, k)] + p[(i, k)] - M * (1 - y[(i, k, j, l)])
                        model += C[(i, k)] >= C[(j, l)] + p[(j, l)] - M * y[(i, k, j, l)]

# --- Solve ---

model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# --- Output ---
# (Optional: printing the result for verification, not strictly required by prompt structure but good practice)
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Total Completion Time (Makespan): {pulp.value(Z)}")

