# Projects and their sessions: (Workstation, Duration)
# Workstations: A, B, C
projects = {
    "Alpha": [("B", 10), ("A", 7), ("C", 10)],
    "Beta":  [("B", 6),  ("C", 2), ("A", 6)],
    "Gamma": [("C", 10), ("A", 6), ("B", 4)]
}

# Sets
P = list(projects.keys())
W = ["A", "B", "C"]

# Pre-calculate session indices for each project
sessions = {}
for p in P:
    sessions[p] = list(range(len(projects[p])))

# Model Initialization
model = pulp.LpProblem("plan", pulp.LpMinimize)

# Decision Variables
# C[p]: Completion time of project p (Continuous)
C = {p: pulp.LpVariable(f"C_{p}", lowBound=0, cat='Continuous') for p in P}

# S[p][i]: Start time of session i of project p (Continuous)
S = {}
for p in P:
    S[p] = {i: pulp.LpVariable(f"S_{p}_{i}", lowBound=0, cat='Continuous') for i in sessions[p]}

# X[p1][i1][p2][i2]: Binary variable for sequencing
# 1 if session i1 of project p1 precedes session i2 of project p2, 0 otherwise
X = {}
# Initialize the nested dictionary structure for X
for p1 in P:
    X[p1] = {}
    for i1 in sessions[p1]:
        X[p1][i1] = {}
        for p2 in P:
            X[p1][i1][p2] = {}
            for i2 in sessions[p2]:
                # Only create one variable per pair to avoid redundancy
                if p1 < p2:
                    X[p1][i1][p2][i2] = pulp.LpVariable(f"X_{p1}_{i1}_{p2}_{i2}", cat='Binary')

# Big M
M = 1000

# Objective Function
# Minimize the total completion time (makespan)
model += pulp.lpSum([C[p] for p in P])

# Constraints

# 1. Project Completion Time Definition
# The completion time of a project is the start time of its last session plus its duration
for p in P:
    last_idx = sessions[p][-1]
    w, d = projects[p][last_idx]
    model += C[p] == S[p][last_idx] + d

# 2. Sequential Sessions within a Project
# A session must start after the previous session in the same project finishes
for p in P:
    for i in range(1, len(sessions[p])):
        prev_w, prev_d = projects[p][i-1]
        model += S[p][i] >= S[p][i-1] + prev_d

# 3. Workstation Capacity (Disjunctive Constraints)
# For any two sessions requiring the same workstation, one must finish before the other starts
for p1 in P:
    for i1 in sessions[p1]:
        w1, d1 = projects[p1][i1]
        for p2 in P:
            for i2 in sessions[p2]:
                if p1 == p2: continue # Same project handled by internal sequence constraints

                w2, d2 = projects[p2][i2]

                if w1 == w2:
                    # Identify the correct X variable based on the order of project names
                    if p1 < p2:
                        x_var = X[p1][i1][p2][i2]
                        # If X=1: p1,i1 before p2,i2
                        # S[p2][i2] >= S[p1][i1] + d1 - M*(1-X)
                        model += S[p2][i2] >= S[p1][i1] + d1 - M * (1 - x_var)

                        # If X=0: p2,i2 before p1,i1
                        # S[p1][i1] >= S[p2][i2] + d2 - M*X
                        model += S[p1][i1] >= S[p2][i2] + d2 - M * x_var

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output Results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Total Completion Time (Objective): {pulp.value(model.objective)}")
