    print(f"  Project Completion: {pulp.value(C[p])}")

import pulp

# Problem Data
# Projects and their sessions: (Workstation, Duration)
# We define a constant set of jobs for the model
jobs = {
    'Alpha': [('B', 10), ('A', 7), ('C', 10)],
    'Beta':  [('B', 6),  ('C', 2), ('A', 6)],
    'Gamma': [('C', 10), ('A', 6), ('B', 4)]
}

# Extract sets
Projects = list(jobs.keys())
Num_Ops = {p: len(sessions) for p, sessions in jobs.items()}
Ops = [(p, i) for p in Projects for i in range(Num_Ops[p])]
Workstations = {'A', 'B', 'C'}

# Session Data
Duration = {}
Machine = {}
for p, sessions in jobs.items():
    for i, (w, d) in enumerate(sessions):
        Duration[p, i] = d
        Machine[p, i] = w

# Big M value
M = 1000

# Model Initialization
model = pulp.LpProblem("plan", pulp.LpMinimize)

# Decision Variables
# C[p, i]: Completion time of operation i of project p
C = pulp.LpVariable.dicts("C", Ops, lowBound=0, cat=pulp.LpContinuous)

# x[p1, i1, p2, i2]: Binary variable, 1 if op (p1,i1) precedes op (p2,i2), 0 otherwise
# Only defined for operations on the same machine that are not part of the same project
Ops_per_Machine = {m: [(p, i) for (p, i) in Ops if Machine[p, i] == m] for m in Workstations}
x = {}
for m in Workstations:
    ops_m = Ops_per_Machine[m]
    for idx1, (p1, i1) in enumerate(ops_m):
        for idx2, (p2, i2) in enumerate(ops_m):
            if p1 != p2: # Different projects
                # To avoid duplicate constraints, we can just take all or half. 
                # Taking all pairs ensures one must be 1 and the other 0 effectively via logic
                # or simply enforce disjunction for every unique pair once.
                # Here we define for all p1!=p2, will constrain indices idx1 < idx2 to avoid redundancy
                if idx1 < idx2:
                    x[p1, i1, p2, i2] = pulp.LpVariable(f"x_{p1}_{i1}_{p2}_{i2}", cat=pulp.LpBinary)

# Objective Function
# Minimize the completion time of the last operation of the last project
# We sum the completion times of all last operations to minimize the max (makespan)
# Since last ops are independent, minimizing sum minimizes the max.
model += pulp.lpSum([C[p, Num_Ops[p]-1] for p in Projects])

# Constraints

# 1. Completion time definition
# C[p, i] >= C[p, i-1] + Duration[p, i]
for p in Projects:
    for i in range(Num_Ops[p]):
        if i == 0:
            model += C[p, i] >= Duration[p, i]
        else:
            model += C[p, i] >= C[p, i-1] + Duration[p, i]

# 2. Disjunctive constraints for machine resources
# For any two operations (p1, i1) and (p2, i2) on the same machine from different projects:
# Either (p1, i1) finishes before (p2, i2) starts, OR vice versa.
# C[p1, i1] + Duration[p1, i1] <= C[p2, i2] + M * (1 - x[p1, i1, p2, i2])
# C[p2, i2] + Duration[p2, i2] <= C[p1, i1] + M * x[p1, i1, p2, i2]

for m in Workstations:
    ops_m = Ops_per_Machine[m]
    for idx1, (p1, i1) in enumerate(ops_m):
        for idx2, (p2, i2) in enumerate(ops_m):
            if p1 != p2 and idx1 < idx2:
                # Ensure x variable exists (it should based on init logic)
                if (p1, i1, p2, i2) in x:
                    model += C[p1, i1] + Duration[p1, i1] <= C[p2, i2] + M * (1 - x[p1, i1, p2, i2])
                    model += C[p2, i2] + Duration[p2, i2] <= C[p1, i1] + M * x[p1, i1, p2, i2]

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output Results (Optional, but good for verification)
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Total Completion Time (Objective): {pulp.value(model.objective)}")
print("\nSchedule:")
for p in sorted(Projects):
    print(f"Project {p}:")
    for i in range(Num_Ops[p]):
        print(f"  Op {i} (WS {Machine[p,i]}): Start {C[p,i].value() - Duration[p,i]}, End {C[p,i].value()}")

